function drawCombat(xmin,ymin,xmax,ymax){const s=cam.scale,a=game.spawner;const visible=(x,y,r=1)=>x+r>xmin&&x-r<xmax&&y+r>ymin&&y-r<ymax;if(visible(a.x+1.5,a.y+1.5,2)){const [x,y]=screen(a.x,a.y);ctx.fillStyle='#733d4a';ctx.fillRect(x+2,y+2,3*s-4,3*s-4);ctx.strokeStyle='#ec827c';ctx.strokeRect(x+2,y+2,3*s-4,3*s-4);ctx.fillStyle='#efad9a';ctx.font=`bold ${s*.24}px system-ui`;ctx.textAlign='center';ctx.fillText('SPAWNER',x+1.5*s,y+1.4*s);ctx.font=`${s*.18}px system-ui`;ctx.fillText(game.combat.enabled?'ACTIVE':'OFF',x+1.5*s,y+1.8*s)}for(const e of game.combat.enemies.values()){if(!visible(e.x,e.y))continue;const [x,y]=screen(e.previousX+(e.x-e.previousX)*interpolation,e.previousY+(e.y-e.previousY)*interpolation);ctx.fillStyle='#ed8277';ctx.fillRect(x-s*.23,y-s*.23,s*.46,s*.46);ctx.fillStyle='#552f3e';ctx.fillRect(x-s*.14,y-s*.08,s*.1,s*.1);ctx.fillRect(x+s*.04,y-s*.08,s*.1,s*.1);ctx.fillStyle='#202532';ctx.fillRect(x-s*.3,y-s*.4,s*.6,3);ctx.fillStyle='#ee9382';ctx.fillRect(x-s*.3,y-s*.4,s*.6*e.hp/e.maxHp,3)}for(const p of game.combat.projectiles){if(!visible(p.x,p.y))continue;const [x,y]=screen(p.previousX+(p.x-p.previousX)*interpolation,p.previousY+(p.y-p.previousY)*interpolation);ctx.fillStyle='#ffdf87';ctx.beginPath();ctx.arc(x,y,Math.max(2,s*.065),0,Math.PI*2);ctx.fill()}for(const e of game.combat.effects){if(!visible(e.x,e.y))continue;const [x,y]=screen(e.x,e.y);ctx.strokeStyle=e.color;ctx.beginPath();ctx.arc(x,y,s*(.4-e.time*.5),0,Math.PI*2);ctx.stroke()}}
function frame(ms){const now=ms/1000,dt=last?Math.max(0,(ms-last)/1000):0;last=ms;const cameraDt=Math.min(.1,dt),speed=9*42/cam.scale;cam.x+=((keys.has('d')||keys.has('arrowright'))-(keys.has('a')||keys.has('arrowleft')))*speed*cameraDt;cam.y+=((keys.has('s')||keys.has('arrowdown'))-(keys.has('w')||keys.has('arrowup')))*speed*cameraDt;cam.x=Math.max(0,Math.min(game.config.width,cam.x));cam.y=Math.max(0,Math.min(game.config.height,cam.y));let t=performance.now();const ticks=clock.advance(dt,step=>game.tick(step),paused||document.hidden);monitoring.simulationMs=ticks?(performance.now()-t)/ticks:monitoring.simulationMs;interpolation=paused||document.hidden?1:clock.alpha;t=performance.now();render(now);monitoring.renderMs=performance.now()-t;monitoring.frames++;monitoring.ticks+=ticks;if(!monitoring.start)monitoring.start=now;if(now-monitoring.start>=1){monitoring.fps=monitoring.frames/(now-monitoring.start);monitoring.tps=monitoring.ticks/(now-monitoring.start);monitoring.frames=0;monitoring.ticks=0;monitoring.start=now;if(settings.debug)$('debug-overlay').textContent=`FPS ${monitoring.fps.toFixed(0)} · TPS ${monitoring.tps.toFixed(1)}
Simulation ${monitoring.simulationMs.toFixed(2)} ms/tick · Render ${monitoring.renderMs.toFixed(2)} ms/frame
Buildings ${game.entities.size} · Belts ${game.beltCount}
Items in transit ${game.network.active.size} · Chunks ${game.grid.chunks.size}
Graph nodes ${game.network.nodes.size} · Catch-up dropped ${clock.dropped}`;}requestAnimationFrame(frame)}requestAnimationFrame(frame);
